'use strict';
// 시간이 지남에 따라 열리는 팬 창작 일상.
const seasonalStories={
 spring_light:{title:'봄의 창가',day:8,when:s=>season()==='봄',lines:[['토모리','창문에 꽃잎이 붙어 있어. 바람이 불어도 안 떨어져.'],['타키','유리에 물기가 남아서 그래. 닦으면 같이 떨어질 텐데.'],['토모리','그럼… 조금만 있다가 닦아도 될까?'],['타키','응. 손님이 오기 전까지만.'],['토모리','고마워. 오늘은 여기서 바깥을 보고 싶어.','smile']]},
 summer_ice:{title:'여름의 물컵',day:8,when:s=>season()==='여름',lines:[['아논','밖에 너무 더워. 들어오자마자 차가운 물부터 마시고 싶다.'],['타키','물은 준비해 뒀어. 급하게 마시지 말고.'],['아논','고마워, 릿키! 손님들도 더우실 텐데 물컵을 잘 보이는 데 두면 좋겠다.'],['타키','얼음이 녹으니까 필요한 만큼만 꺼내 놓자.'],['아논','그럼 내가 빈 컵 채워 둘게.']]},
 autumn_leaf:{title:'가을의 낙엽',day:15,when:s=>season()==='가을',lines:[['라나','밖에 바삭한 게 많아.'],['아논','낙엽 말하는 거야? 방금 밟는 소리 들렸어.'],['라나','응. 조금씩 다르게 나.','curious'],['타키','실내까지 가져오진 마. 방금 바닥 닦았으니까.'],['라나','알아. 밖에서 들을게.'],['아논','나도 같이 가 볼래!']]},
 winter_warm:{title:'겨울의 온기',day:22,when:s=>season()==='겨울',lines:[['소요','손이 많이 차갑네. 컵을 잠깐 잡고 있어도 될까?'],['타키','아직 뜨거우니까 조심해. 손잡이를 잡는 게 나아.'],['소요','응. 따뜻하다.'],['토모리','밖에서 기다리던 사람들도… 따뜻해지면 좋겠어.'],['타키','문 가까운 자리부터 정리해 둘게. 들어오면 바로 앉을 수 있게.']]},
 rain_umbrella:{title:'비 오는 날의 입구',day:10,when:s=>rainy(),lines:[['타키','우산에서 물이 떨어져서 입구가 미끄럽네.'],['아논','매트가 젖었어. 내가 새 걸 가져올까?'],['타키','응. 그동안 나는 이쪽을 닦을게.'],['아논','알겠어. 손님들 들어올 때 조심하라고도 말해 둘게.'],['타키','고마워. 통로는 비워 둬야 하니까 매트는 벽 쪽에 놓자.']]}
};

// 계절의 작은 사건을 마무리하되 기존 대화 번호는 유지한다.
seasonalStories.spring_light.lines.push(
 ['토모리','꽃잎 그림자가 유리 안쪽에도 있어.'],
 ['타키','햇빛 때문에 생겼네. 조금 있으면 자리도 바뀔걸.'],
 ['토모리','그럼 꽃잎은 그대로인데 그림자만 움직이는 거야?'],
 ['타키','해가 움직이니까. …아, 벌써 조금 내려갔어.'],
 ['토모리','응. 닦기 전까지 어디까지 가는지 보고 싶어.'],
 ['타키','손님 오기 전에 알려 줘. 그때는 같이 닦자.']
);
seasonalStories.summer_ice.lines.push(
 ['아논','컵은 여기에 두면 보이겠지?'],
 ['타키','직사광선이 닿아. 얼음은 안에 두고 컵만 꺼내 놔.'],
 ['아논','아, 그러면 물도 미지근해지겠다.'],
 ['타키','필요하면 바로 채워 드리면 돼. 손님이 지나갈 곳은 남겨 두고.'],
 ['아논','이쪽으로 조금 옮길게. …어때, 길은 안 막지?'],
 ['타키','응. 이제 네 물도 마셔. 아까 덥다고 했잖아.'],
 ['아논','맞다! 컵 놓느라 내 건 깜빡했네.']
);
seasonalStories.autumn_leaf.lines.push(
 ['아논','이쪽 잎은 조용한데? 같은 나무에서 떨어진 것 같은데도.'],
 ['라나','젖었어.'],
 ['아논','아, 마른 것만 바삭거리는구나.'],
 ['라나','저쪽은 더 크게 나.'],
 ['타키','밖에서만 듣는다더니 문 앞에서 계속 서 있을 거야? 손님 지나가야 해.'],
 ['아논','앗, 길 막고 있었네. 안쪽으로 비켜 줄게!'],
 ['라나','나중에 다시 들을래.'],
 ['타키','응. 연습 끝나고.']
);
seasonalStories.winter_warm.lines.push(
 ['소요','의자를 너무 문 가까이 두면 문을 열 때 부딪히겠다.'],
 ['타키','통로는 이만큼 남겨야 해. 조금 안쪽으로 옮길게.'],
 ['토모리','여기면 문이 열려도… 바로 바람이 닿지 않을 것 같아.'],
 ['소요','토모리 쨩이 앉아서 확인해 줄래?'],
 ['토모리','응. …아까보다 따뜻해.'],
 ['타키','그럼 이 자리는 그대로 두자. 다음 손님 오기 전에 물도 가져올게.'],
 ['소요','컵 잡고 있으니까 손이 좀 풀렸어. 의자는 내가 제자리에 놓을게.']
);
seasonalStories.rain_umbrella.lines.push(
 ['아논','새 매트 가져왔어. 젖은 건 어디에 둘까?'],
 ['타키','창고 앞에 걸어 둬. 바닥에 겹쳐 놓으면 마르지 않으니까.'],
 ['아논','여기 걸면 문이 안 열리는데… 조금 옆으로.'],
 ['타키','응. 그쪽이면 괜찮아.'],
 ['아논','우산 놓을 곳도 손님한테 보이게 해야겠다.'],
 ['타키','문 옆에 있어. 안내할 때 발밑부터 조심하시라고 말해 줘.'],
 ['아논','알았어. 릿키도 방금 닦은 데 밟지 마!'],
 ['타키','…말 안 해도 알아.']
);
